class LRUCache:
    """ 
    A Least Recently Used (LRU) Cache implemented using a dictionary and a 
    doubly linked list, but leveraging a single list for efficiently storing 
    the most recently used keys while maintaining their order.
    """

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key].value
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key].value = value
            self.order.remove(key)
        elif len(self.cache) >= self.capacity:
            lru_key = self.order.pop(0)
            del self.cache[lru_key]
        self.cache[key] = self.Node(key, value)
        self.order.append(key)
